body.script:
/**/
// Aether Onefile web proxy (Scramjet V1 + BareMux + Epoxy), running from static files.
// sw.js, scram/, baremux/ and epoxy/ must sit in the same folder as onefile.svg.
(function () {
  // ===== EDIT THIS: your Aether server's Wisp address, e.g. "wss://aether.example.com/" =====
  var AETHER_WISP = "wss://testgradesstudy.org/";
  // ===========================================================================================

  // Folder that onefile.svg was loaded from (works on jsDelivr, staticdelivr, GitHub Pages…)
  var P = location.pathname.replace(/[^\/]*$/, "") || "/";

  function cleanWisp(url) {
    try {
      var u = new URL(String(url || "").trim());
      if (u.protocol !== "wss:" && u.protocol !== "ws:") return "";
      if (!/\/$/.test(u.pathname)) u.pathname += "/";
      return u.href;
    } catch (e) { return ""; }
  }
  function getWisp() {
    var saved = "";
    try { saved = localStorage.getItem("aether-wisp"); } catch (e) {}
    return cleanWisp(saved) || cleanWisp(AETHER_WISP);
  }
  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = src;
      s.async = false;
      s.onload = resolve;
      s.onerror = function () { reject(new Error("Couldn't load " + src)); };
      document.head.appendChild(s);
    });
  }

  function deleteDb(name) {
    return new Promise(function (r) {
      try { var q = indexedDB.deleteDatabase(name); q.onsuccess = q.onerror = function () { r(); }; q.onblocked = function () { setTimeout(r, 1500); }; }
      catch (e) { r(); }
    });
  }
  function makeController() {
    var ScramjetController = window.$scramjetLoadController().ScramjetController;
    return new ScramjetController({
      prefix: P + "scramjet/",
      files: {
        wasm: P + "scram/scramjet.wasm.wasm",
        all: P + "scram/scramjet.all.js",
        sync: P + "scram/scramjet.sync.js",
      },
    });
  }

  // 1) Scramjet sets up its database first (if the service worker opens it first it ends up empty).
  var sjReady = (async function () {
    await loadScript(P + "scram/scramjet.all.js");
    var sj = makeController();
    try {
      await sj.init();
    } catch (e) {
      // Broken storage from an older build: drop the old worker + database and rebuild once.
      console.warn("Aether Onefile: resetting Scramjet storage", e);
      try {
        var regs = await navigator.serviceWorker.getRegistrations();
        await Promise.all(regs.map(function (r) { return r.unregister(); }));
      } catch (e2) {}
      await deleteDb("$scramjet");
      sj = makeController();
      await sj.init();
    }
    return sj;
  })();

  // 2) Then the service worker (games need it too: it fixes jsDelivr's text/plain .html).
  var swReady = sjReady.catch(function () {}).then(function () {
    if (!("serviceWorker" in navigator)) throw new Error("This browser doesn't support service workers.");
    return navigator.serviceWorker.register(P + "sw.js", { scope: P, updateViaCache: "none" });
  }).then(function (reg) {
    try { reg.update(); } catch (e) {}
    return navigator.serviceWorker.ready;
  });
  // Frames that load our own .html wait for this (max 8 s) — see the SVG shim.
  window.__aetherSwReady = Promise.race([
    swReady.catch(function (e) { console.error("Aether Onefile: service worker", e); }),
    new Promise(function (r) { setTimeout(r, 8000); }),
  ]).then(function () { window.__aetherSwOk = true; });

  // 3) Then the network transport through your Wisp server.
  async function init() {
    var sj = await sjReady;
    await swReady;
    var wisp = getWisp();
    if (!wisp) throw new Error("No Wisp server is set. Put your Wisp address in AETHER_WISP inside onefile.svg.");
    await loadScript(P + "baremux/index.js");

    var conn = new window.BareMux.BareMuxConnection(P + "baremux/worker.js");
    // Some CDNs (staticdelivr) serve .mjs with a non-JavaScript type, which browsers refuse to import.
    // So the Epoxy module is shipped as epoxy/index.esm.js; if even that fails, import it from a data: URL.
    var opts = [{ wisp: wisp }];
    try {
      await conn.setTransport(P + "epoxy/index.esm.js", opts);
    } catch (e) {
      // index.esm.js missing or served with the wrong type: read the module's text ourselves
      // (fetch doesn't care about the content type) and import it from a data: URL.
      console.warn("Aether Onefile: loading Epoxy from a data URL", e);
      var code = null, files = ["epoxy/index.esm.js", "epoxy/index.mjs"];
      for (var i = 0; i < files.length && code === null; i++) {
        try {
          var r = await fetch(P + files[i], { cache: "no-store" });
          var t = r.ok ? await r.text() : "";
          if (t && !/^\s*</.test(t)) code = t;
        } catch (e2) {}
      }
      if (code === null) throw new Error("Couldn't load the Epoxy transport (epoxy/index.mjs). Make sure the epoxy folder is uploaded next to onefile.svg.");
      var bytes = new TextEncoder().encode(code), bin = "";
      for (var j = 0; j < bytes.length; j += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(j, j + 0x8000));
      await conn.setTransport("data:text/javascript;base64," + btoa(bin), opts);
    }

    window.scramjet = sj;
    window.aetherEncode = function (url) { return sj.encodeUrl(url); };
    window.aetherEngine = "scramjet-v1";
    window.aetherTransport = "epoxy";
    window.dispatchEvent(new Event("aether-ready"));
  }

  window.aetherReady = init().catch(function (err) {
    console.error("Aether Onefile: proxy failed to start", err);
    window.aetherError = err;
    window.dispatchEvent(new CustomEvent("aether-error", { detail: err.message }));
    throw err;
  });
  window.aetherReady.catch(function () {});
})();

