async function openLegalPage(fileUrl, title, aetherUrl) {
  const tab = tabs.find((t) => t.id === activeTabId);
  if (!tab) return;

  tab.url = aetherUrl;
  tab.frameWrap.innerHTML = `<div class="content-page"><div class="content-title">Loading...</div></div>`;
  addressBar.value = aetherUrl;
  tab.tabBtn.querySelector(".tab-title").textContent = title;
  if (typeof setTabIcon === "function") setTabIcon(tab, true);
  document.getElementById("menu-btn").classList.add("hidden");

  try {
    const res = await fetch(fileUrl);
    const html = await res.text();
    const doc = new DOMParser().parseFromString(html, "text/html");
    const bodyContent = doc.body.innerHTML;

    const wrap = document.createElement("div");
    wrap.className = "content-page legal-page";
    wrap.innerHTML = `
      <div class="legal-page-close"><i class="fa-solid fa-xmark"></i></div>
      <div class="content-title">${title}</div>
      <div class="legal-page-body">${bodyContent}</div>
    `;

    wrap.querySelector(".legal-page-close").onclick = () => {
      tab.url = null;
      tab.frameWrap.innerHTML = "";
      tab.frameWrap.appendChild(buildNewTabPage(tab.id));
      addressBar.value = "aether://newtab";
      tab.tabBtn.querySelector(".tab-title").textContent = "Aether";
      if (typeof setTabIcon === "function") setTabIcon(tab, true);
    };

    tab.frameWrap.innerHTML = "";
    tab.frameWrap.appendChild(wrap);
  } catch (err) {
    tab.frameWrap.innerHTML = `<div class="content-page"><div class="content-title">Failed to load</div></div>`;
    console.error(`Aether: failed to load ${fileUrl}`, err);
  }
}

