          <div class="theme-swatch" style="background:${vars["--c-surface-2"]}"></div>
          <div class="theme-swatch" style="background:${vars["--c-accent"]}"></div>
        `;
      }
    }

    select.value = getCurrentThemeId();
    updatePreview();

    select.addEventListener("change", () => {
      applyTheme(select.value);
      updatePreview();
    });
  }

