/**/

/**/
(() => {
  const FLAKES_PER_PIXEL = 1 / 14000;
  const MAX_FLAKES = 140;
  const layers = new Set();

  function snowWanted() {
    const winter = typeof getCurrentSeason === "function" && getCurrentSeason() === "winter";
    const on = typeof getUiPref === "function" ? getUiPref("snow") === "on" : true;
    const calm = typeof reduceMotionOn === "function" && reduceMotionOn();
    return winter && on && !calm;
  }

  function makeFlake(w, h, anywhere) {
    const r = Math.random() * 2.2 + 0.8;
    return {
      x: Math.random() * w,
      y: anywhere ? Math.random() * h : -10 - Math.random() * 40,
      r,
      speed: 0.25 + r * 0.22 + Math.random() * 0.3,
      drift: Math.random() * Math.PI * 2,
      sway: 0.3 + Math.random() * 0.6,
      alpha: 0.35 + Math.random() * 0.5,
    };
  }

  function attach(page) {
    if (page._snow) return;
    const canvas = document.createElement("canvas");
    canvas.className = "snow-canvas";
    canvas.setAttribute("aria-hidden", "true");
    page.prepend(canvas);
    const ctx = canvas.getContext("2d");
    const layer = { page, canvas, ctx, flakes: [], w: 0, h: 0, raf: 0 };
    page._snow = layer;
    layers.add(layer);

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      layer.w = page.clientWidth;
      layer.h = page.clientHeight;
      canvas.width = Math.max(1, Math.round(layer.w * dpr));
      canvas.height = Math.max(1, Math.round(layer.h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const want = Math.min(MAX_FLAKES, Math.round(layer.w * layer.h * FLAKES_PER_PIXEL));
      while (layer.flakes.length < want) layer.flakes.push(makeFlake(layer.w, layer.h, true));
      layer.flakes.length = want;
    };
    layer.resize = resize;
    if (window.ResizeObserver) new ResizeObserver(resize).observe(page);
    resize();
    tick();
  }

  function frame(layer, dt) {
    const { ctx, w, h, flakes } = layer;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#ffffff";
    for (const f of flakes) {
      f.drift += 0.012 * dt;
      f.y += f.speed * dt;
      f.x += Math.sin(f.drift) * f.sway * 0.5 * dt;
      if (f.y > h + 6) Object.assign(f, makeFlake(w, h, false));
      if (f.x < -6) f.x = w + 6;
      else if (f.x > w + 6) f.x = -6;
      ctx.globalAlpha = f.alpha;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  let running = false;
  let last = 0;

  function tick() {
    if (running) return;
    running = true;
    last = performance.now();
    requestAnimationFrame(loop);
  }

  function loop(now) {
    const dt = Math.min(3, (now - last) / 16.67);
    last = now;
    let any = false;
    const wanted = snowWanted();
    for (const layer of layers) {
      if (!layer.page.isConnected) {
        layers.delete(layer);
        continue;
      }
      const show = wanted && layer.page.offsetParent !== null && document.visibilityState === "visible";
      const disp = wanted ? "block" : "none";
      if (layer.canvas.style.display !== disp) layer.canvas.style.display = disp;
      if (show) {
        if (!layer.w) layer.resize();
        frame(layer, dt);
        any = true;
      }
    }
    if (any) requestAnimationFrame(loop);
    else running = false;
  }

  function scan() {
    document.querySelectorAll(".newtab-page").forEach(attach);
    if (snowWanted()) tick();
    else
      layers.forEach((l) => {
        if (l.canvas.style.display !== "none") l.canvas.style.display = "none";
      });
  }

  const content = document.getElementById("tabcontent");
  if (content) new MutationObserver(scan).observe(content, { childList: true, subtree: true, attributes: true, attributeFilter: ["style"] });
  document.addEventListener("visibilitychange", scan);
  window.addEventListener("aether-uiprefs", scan);
  setInterval(scan, 60 * 1000);
  scan();
  window.aetherSnowRefresh = scan;
})();

/**/

/**/
const FEEDBACK_TYPES = ["Feature request", "Game / app request", "Bug report", "Other"];
const FEEDBACK_COOLDOWN_MS = 60 * 1000;

function openFeedbackModal() {
  if (document.querySelector(".feedback-overlay")) return;

  const overlay = document.createElement("div");
  overlay.className = "feedback-overlay";
  overlay.innerHTML = `
    <div class="feedback-card">
      <div class="feedback-header">
        <div class="feedback-title">Submit a Request</div>
        <div class="feedback-close"><i class="fa-solid fa-xmark"></i></div>
      </div>
      <div class="feedback-body">
        <label class="feedback-label">What kind of request?</label>
        <select class="feedback-select">
          ${FEEDBACK_TYPES.map((t) => `<option value="${t}">${t}</option>`).join("")}
        </select>

        <label class="feedback-label">Your message</label>
        <textarea class="feedback-textarea" maxlength="1000" placeholder="Tell us what you'd like to see, or what's broken..."></textarea>
        <div class="feedback-counter">0 / 1000</div>

        <label class="feedback-label">Contact (optional)</label>
        <input class="feedback-input" maxlength="100" placeholder="Discord username or email, if you want a reply" />

        <input class="feedback-honeypot" name="website" tabindex="-1" autocomplete="off" />

        <div class="feedback-status"></div>
        <button class="feedback-submit">Send</button>
      </div>
    </div>
  `;

  const close = () => overlay.remove();
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) close();
  });
  overlay.querySelector(".feedback-close").onclick = close;

  const select = overlay.querySelector(".feedback-select");
  const textarea = overlay.querySelector(".feedback-textarea");
  const counter = overlay.querySelector(".feedback-counter");
  const contactInput = overlay.querySelector(".feedback-input");
  const honeypot = overlay.querySelector(".feedback-honeypot");
  const status = overlay.querySelector(".feedback-status");
  const submit = overlay.querySelector(".feedback-submit");

  function setStatus(text, kind) {
    status.textContent = text;
    status.className = "feedback-status" + (kind ? ` ${kind}` : "");
  }

  textarea.addEventListener("input", () => {
    counter.textContent = `${textarea.value.length} / 1000`;
  });

  submit.onclick = async () => {
    const message = textarea.value.trim();
    if (message.length < 5) {
      setStatus("Write at least a few words first.", "error");
      return;
    }

    const last = Number(localStorage.getItem("aether-feedback-last") || 0);
    if (Date.now() - last < FEEDBACK_COOLDOWN_MS) {
      setStatus("Give it a few seconds before sending another.", "error");
      return;
    }

    submit.disabled = true;
    setStatus("Sending...", "");

    try {
      const res = await fetch("/api/feedback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: select.value,
          message,
          contact: contactInput.value.trim(),
          website: honeypot.value,
        }),
      });
      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        setStatus(data.error || "Something went wrong. Try again.", "error");
        submit.disabled = false;
        return;
      }

      localStorage.setItem("aether-feedback-last", String(Date.now()));
      if (data.requests === 10) setStatus("Sent! You earned the Bug hunter badge!", "success");
      else if (typeof data.requests === "number" && data.requests < 10) setStatus(`Sent! Thanks for the feedback. (${data.requests}/10 toward the Bug hunter badge)`, "success");
      else setStatus("Sent! Thanks for the feedback.", "success");
      setTimeout(close, 2200);
    } catch (err) {
      console.error("Aether: feedback failed", err);
      setStatus("Couldn't reach the server. Try again.", "error");
      submit.disabled = false;
    }
  };

  document.body.appendChild(overlay);
  textarea.focus();
}

function buildFeedbackButton() {
  const btn = document.createElement("div");
  btn.className = "feedback-btn";
  btn.innerHTML = `<i class="fa-solid fa-comment-dots"></i> Submit a request`;
  btn.onclick = openFeedbackModal;
  return btn;
}
/**/

/**/
(function () {
  const API = (window.AETHER_API_BASE || "") + "/api/suggest";

  function skip(v) {
    return !v || /^[a-z][a-z0-9+.-]*:\/\//i.test(v) || /^\S+\.[a-z]{2,}(\/\S*)?$/i.test(v);
  }

  window.attachSuggest = function attachSuggest(input, opts = {}) {
    const anchor = opts.anchor || input.parentElement;
    const list = document.createElement("div");
    list.className = "sg-list";
    list.hidden = true;
    anchor.appendChild(list);

    let items = [];
    let active = -1;
    let typed = "";
    let timer = null;
    let ctrl = null;

    function close() {
      list.hidden = true;
      list.innerHTML = "";
      items = [];
      active = -1;
    }

    function mark() {
      [...list.children].forEach((el, i) => el.classList.toggle("active", i === active));
    }

    function pick(text) {
      input.value = text;
      close();
      if (opts.onSubmit) opts.onSubmit(text);
    }

    function render() {
      list.innerHTML = "";
      items.forEach((text, i) => {
        const row = document.createElement("div");
        row.className = "sg-row";
        const icon = document.createElement("i");
        icon.className = "fa-solid fa-magnifying-glass";
        const label = document.createElement("span");
        const lower = text.toLowerCase();
        const t = typed.toLowerCase();
        if (lower.startsWith(t)) {
          label.append(document.createTextNode(text.slice(0, typed.length)));
          const b = document.createElement("b");
          b.textContent = text.slice(typed.length);
          label.appendChild(b);
        } else {
          label.textContent = text;
        }
        row.append(icon, label);
        row.addEventListener("mousedown", (e) => {
          e.preventDefault();
          pick(text);
        });
        row.addEventListener("mousemove", () => {
          active = i;
          mark();
        });
        list.appendChild(row);
      });
      list.hidden = !items.length;
    }

    async function fetchSuggestions(q) {
      if (ctrl) ctrl.abort();
      ctrl = new AbortController();
      try {
        const r = await fetch(`${API}?q=${encodeURIComponent(q)}`, { signal: ctrl.signal });
        if (!r.ok) return close();
        const data = await r.json();
        if (input.value.trim() !== q) return;
        items = Array.isArray(data) ? data.filter((s) => s.toLowerCase() !== q.toLowerCase()).slice(0, 8) : [];
        active = -1;
        typed = q;
        render();
      } catch {
      }
    }

    input.addEventListener("input", () => {
      clearTimeout(timer);
      const q = input.value.trim();
      if (skip(q)) return close();
      timer = setTimeout(() => fetchSuggestions(q), 120);
    });

    input.addEventListener("keydown", (e) => {
      if (list.hidden || !items.length) return;
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        active = e.key === "ArrowDown" ? (active + 1) % items.length : (active - 1 + items.length) % items.length;
        input.value = items[active];
        mark();
      } else if (e.key === "Escape") {
        input.value = typed;
        close();
      } else if (e.key === "Enter") {
        close();
      }
    });

    input.addEventListener("blur", () => setTimeout(close, 120));
    input.addEventListener("focus", () => {
      const q = input.value.trim();
      if (!skip(q) && q === typed && items.length) render();
    });
  };

  const bar = document.getElementById("address-bar");
  if (bar) attachSuggest(bar, { anchor: document.getElementById("address-wrap"), onSubmit: (t) => navigate(t) });
})();
