  if (window.updateOnlineBadge) window.updateOnlineBadge(onlineBadge);

  wrap.appendChild(clock);
  wrap.appendChild(dateEl);
  wrap.appendChild(searchBar);
  wrap.appendChild(shortcutsGrid);
  wrap.appendChild(quote);
  wrap.appendChild(updateBtn);
  wrap.appendChild(onlineBadge);
  wrap.appendChild(buildFeedbackButton());

  return wrap;
}

function tabIconHtml(internal) {
  return internal
    ? `<img class="tab-fav" src="${window.aetherTabIcon || "/favicon-32.png"}" alt="">`
    : '<i class="fa-solid fa-globe"></i>';
}

function setTabIcon(tab, internal) {
  const holder = tab.tabBtn.querySelector(".tab-icon");
  if (holder) holder.innerHTML = tabIconHtml(internal);
}

function createTab(url, options = {}) {
  const id = crypto?.randomUUID?.() ||
(Date.now().toString(36) + Math.random().toString(36));

  const frameWrap = document.createElement("div");
  frameWrap.style.position = "absolute";
  frameWrap.style.inset = "0";
  frameWrap.style.display = "none";

  if (!url) {
    frameWrap.appendChild(buildNewTabPage(id));
  } else {
    const isExternal = /^https?:\/\//i.test(url);
    const iframe = document.createElement("iframe");
    if (!isExternal) iframe.src = url;
    frameWrap.appendChild(iframe);
    loadAetherFrame(iframe, url);
    addToHistory(url);
    if (options.showLaunchLoading) {
      showLaunchLoading(frameWrap, iframe, options.appName || url);
    }
  }

  contentEl.appendChild(frameWrap);

  const tabBtn = document.createElement("div");
  tabBtn.className = "tab";
  tabBtn.draggable = true;
  tabBtn.dataset.tabId = id;
  tabBtn.innerHTML = `<span class="tab-icon">${tabIconHtml(!/^https?:\/\//i.test(url || ""))}</span><span class="tab-title"></span><span class="close-btn">×</span>`;
  tabBtn.querySelector(".tab-title").textContent = options.appName || (url ? displayUrl(url) : "Aether");
  tabBtn.onclick = (e) => {
    if (e.target.classList.contains("close-btn")) closeTab(id);
    else switchTab(id);
  };

  tabBtn.addEventListener("dragstart", () => {
    tabBtn.classList.add("dragging");
  });
  tabBtn.addEventListener("dragend", () => {
    tabBtn.classList.remove("dragging");
    tabsEl.querySelectorAll(".tab").forEach((t) => t.classList.remove("drag-over"));
  });
  tabBtn.addEventListener("dragover", (e) => {
    e.preventDefault();
    tabBtn.classList.add("drag-over");
  });
  tabBtn.addEventListener("dragleave", () => {
    tabBtn.classList.remove("drag-over");
  });
  tabBtn.addEventListener("drop", (e) => {
    e.preventDefault();
    tabBtn.classList.remove("drag-over");
    const draggingEl = tabsEl.querySelector(".tab.dragging");
    if (!draggingEl || draggingEl === tabBtn) return;

    const draggedId = draggingEl.dataset.tabId;
    tabBtn.before(draggingEl);

    const draggedIdx = tabs.findIndex((t) => t.id === draggedId);
    const [draggedTab] = tabs.splice(draggedIdx, 1);
    const targetIdx = tabs.findIndex((t) => t.id === id);
    tabs.splice(targetIdx, 0, draggedTab);
  });

  document.getElementById("newtab-btn").before(tabBtn);

  const tab = { id, frameWrap, tabBtn, hist: [], hpos: -1, skipRecord: false, frame: { depth: 0, fwd: 0, expect: 0 } };
  let currentUrl = url;
  Object.defineProperty(tab, "url", {
    enumerable: true,
    get: () => currentUrl,
    set: (v) => {
      currentUrl = v;
      tabRecord(tab, v);
    },
  });
  tabRecord(tab, url);
  tabs.push(tab);
  switchTab(id);
  return id;
}

function tabRecord(tab, url) {
  const loc = url || "aether://newtab";
  tab.frame = { depth: 0, fwd: 0, expect: 0 };
  if (tab.skipRecord) {
    tab.skipRecord = false;
  } else if (tab.hist[tab.hpos] !== loc) {
    tab.hist = tab.hist.slice(0, tab.hpos + 1);
    tab.hist.push(loc);
    if (tab.hist.length > 100) tab.hist.shift();
    tab.hpos = tab.hist.length - 1;
  }
  setTimeout(() => {
    tabWatchFrame(tab);
    syncNavButtons();
  }, 0);
}

function tabWatchFrame(tab) {
  const iframe = tab.frameWrap.querySelector("iframe");
  if (!iframe || iframe._navWatch) return;
  iframe._navWatch = true;
  iframe.addEventListener("load", () => {
    let href = "";
    try {
      href = iframe.contentWindow.location.href;
    } catch {
      href = "cross-origin";
    }
    if (!href || href === "about:blank") return;
    if (!iframe._navBase) {
      iframe._navBase = true;
      iframe._navLen = history.length;
      return;
    }
    const f = tab.frame;
    if (f.expect > 0) f.expect--;
    else {
      f.depth++;
      f.fwd = 0;
    }
    syncNavButtons();
  });
}

function tabFrame(tab) {
  const iframe = tab && tab.frameWrap.querySelector("iframe");
  if (!iframe || !iframe._navBase) return null;
  try {
    return iframe.contentWindow.history ? iframe : null;
  } catch {
    return null;
  }
}

function canFrameBack(tab) {
  const iframe = tabFrame(tab);
  return Boolean(iframe && tab.frame.depth > 0 && history.length > (iframe._navLen || 0));
}

function canFrameForward(tab) {
  return Boolean(tabFrame(tab) && tab.frame.fwd > 0);
}

function goTabHistory(tab, pos) {
  if (pos < 0 || pos >= tab.hist.length) return;
  tab.hpos = pos;
  const loc = tab.hist[pos];
  tab.skipRecord = true;
  setTimeout(() => {
    tab.skipRecord = false;
  }, 3000);
  if (loc === "aether://newtab") document.getElementById("home-btn").onclick();
  else if (/^aether:\/\//i.test(loc)) openAetherUrl(loc, tab.id);
  else navigate(loc, tab.id);
  syncNavButtons();
}

function goBack() {
  const tab = tabs.find((t) => t.id === activeTabId);
  if (!tab) return;
  if (canFrameBack(tab)) {
    try {
      tabFrame(tab).contentWindow.history.back();
      tab.frame.depth--;
      tab.frame.fwd++;
      tab.frame.expect++;
      return syncNavButtons();
    } catch {
    }
  }
  if (tab.hpos > 0) goTabHistory(tab, tab.hpos - 1);
}

function goForward() {
  const tab = tabs.find((t) => t.id === activeTabId);
  if (!tab) return;
  if (canFrameForward(tab)) {
    try {
      tabFrame(tab).contentWindow.history.forward();
      tab.frame.fwd--;
      tab.frame.depth++;
      tab.frame.expect++;
      return syncNavButtons();
    } catch {
    }
  }
  if (tab.hpos < tab.hist.length - 1) goTabHistory(tab, tab.hpos + 1);
}

function syncNavButtons() {
  const tab = tabs.find((t) => t.id === activeTabId);
  const back = document.getElementById("back-btn");
  const fwd = document.getElementById("forward-btn");
  if (!back || !fwd) return;
  back.disabled = !tab || !(canFrameBack(tab) || tab.hpos > 0);
  fwd.disabled = !tab || !(canFrameForward(tab) || tab.hpos < tab.hist.length - 1);
}

document.getElementById("back-btn").onclick = goBack;
document.getElementById("forward-btn").onclick = goForward;
document.addEventListener("keydown", (e) => {
  if (!e.altKey || e.ctrlKey || e.metaKey) return;
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    goBack();
  } else if (e.key === "ArrowRight") {
    e.preventDefault();
    goForward();
  }
});

function switchTab(id) {
  tabs.forEach((t) => {
    t.frameWrap.style.display = t.id === id ? "block" : "none";
    t.tabBtn.classList.toggle("active", t.id === id);
  });
  activeTabId = id;
  const tab = tabs.find((t) => t.id === id);
  addressBar.value = displayUrl(tab.url);
  updateLock();
  syncMenuButton();
  syncNavButtons();
  window.dispatchEvent(new Event("aether-urlchange"));
}

let musicTabId = null;

function stopTabAudio(tab) {
  tab.frameWrap.querySelectorAll("audio, video").forEach((m) => {
    try {
      m.pause();
    } catch {
    }
  });
  tab.frameWrap.querySelectorAll("iframe").forEach((f) => {
    try {
      f.src = "about:blank";
    } catch {
    }
  });
  if (tab.id === musicTabId) {
    musicTabId = null;
    if (typeof musicStopAll === "function") musicStopAll();
  }
}

function closeTab(id) {
  const idx = tabs.findIndex((t) => t.id === id);
  if (idx === -1) return;
  stopTabAudio(tabs[idx]);
  tabs[idx].frameWrap.remove();
  tabs[idx].tabBtn.remove();
  tabs.splice(idx, 1);
  if (activeTabId === id) {
    if (tabs.length) switchTab(tabs[tabs.length - 1].id);
    else createTab();
  }
}

function navigate(rawInput, tabId, title) {
  let url = rawInput.trim();
  if (/^aether:\/\//i.test(url)) {
    openAetherUrl(url, tabId);
    return;
  }
  const looksLikeUrl = /^https?:\/\//i.test(url) || /\.[a-z]{2,}(\/|$)/i.test(url);

  if (url.startsWith("/") && !url.startsWith("//")) {
  } else if (!looksLikeUrl) {
    url = "https://duckduckgo.com/?q=" + encodeURIComponent(url);
  } else if (!/^https?:\/\//i.test(url)) {
    url = "https://" + url;
  }

  const id = tabId || activeTabId;
  const tab = tabs.find((t) => t.id === id);
  if (!tab) return;

  tab.url = url;
  tab.frameWrap.innerHTML = "";
  const isExternal = /^https?:\/\//i.test(url);
  const iframe = document.createElement("iframe");
  if (!isExternal) iframe.src = url;
  tab.frameWrap.appendChild(iframe);
  loadAetherFrame(iframe, url);
  tab.tabBtn.querySelector(".tab-title").textContent = title || displayUrl(url);
  setTabIcon(tab, !isExternal);
  addToHistory(url);

  if (id === activeTabId) {
    addressBar.value = displayUrl(url);
    updateLock();
    window.dispatchEvent(new Event("aether-urlchange"));
  }
}

updateLock();
addressBar.addEventListener("keydown", (e) => {
  if (e.key === "Enter") navigate(addressBar.value);
});

document.getElementById("menu-btn").onclick = () => {
  document.getElementById("sidebar").classList.add("open");
  document.getElementById("menu-btn").classList.add("hidden");
};

document.getElementById("sidebar-close").onclick = () => {
  document.getElementById("sidebar").classList.remove("open");
  document.getElementById("menu-btn").classList.remove("hidden");
