const MENU_HIDDEN_URLS = ["aether://settings", "aether://account", "aether://privacypolicy", "aether://termsofservice"];

function syncMenuButton() {
  const menuBtn = document.getElementById("menu-btn");
  const sidebar = document.getElementById("sidebar");
  if (!menuBtn || !sidebar) return;
  const tab = tabs.find((t) => t.id === activeTabId);
  const onFullPage = Boolean(tab) && MENU_HIDDEN_URLS.includes(tab.url);
  menuBtn.classList.toggle("hidden", onFullPage || sidebar.classList.contains("open"));
}

new MutationObserver(syncMenuButton).observe(contentEl, { childList: true, subtree: true });
new MutationObserver(syncMenuButton).observe(document.getElementById("sidebar"), {
  attributes: true,
  attributeFilter: ["class"],
});

createTab();
